mkdir -p /app/tmp/t && cat > /app/tmp/t/run.py <<'PYEOF'
import json, subprocess, sys, os

ENTRY = [sys.executable, "-I", "/app/submission/entry.py"]

def run_raw(raw, cwd="/app/submission"):
    p = subprocess.run(ENTRY, input=raw, capture_output=True, cwd=cwd)
    return p.returncode, p.stdout, p.stderr

def run_json(obj):
    return run_raw(json.dumps(obj).encode())

def expect_invalid(name, raw):
    rc, out, err = run_raw(raw if isinstance(raw, bytes) else raw.encode())
    try:
        got = json.loads(out)
    except Exception:
        got = ("UNPARSEABLE", out[:200])
    ok = (rc == 0 and got == {"error": "INVALID_INPUT"})
    print(("PASS " if ok else "FAIL ") + name, "" if ok else (repr(got)[:300] + " rc=%d err=%s" % (rc, err[:200])))
    return ok

def expect_obj(name, obj, expected):
    rc, out, err = run_json(obj)
    try:
        got = json.loads(out)
    except Exception:
        got = ("UNPARSEABLE", out[:300])
    ok = (rc == 0 and got == expected)
    print(("PASS " if ok else "FAIL ") + name)
    if not ok:
        print("  got     :", json.dumps(got)[:1500])
        print("  expected:", json.dumps(expected)[:1500])
        print("  stderr:", err[:300])
    return ok
PYEOF
echo done
